	["%s: %d frames"] = "%s: %d Rahmen",
	["Drag to move. Right-click when done."] = "Zum Verschieben ziehen. Rechtsklick zum Beenden.",
	["Drag to scale"] = "Zum Skalieren ziehen",
	["Hold Alt while you drag to change the width or the height."] = "Beim Ziehen Alt halten, um Breite oder Höhe zu ändern.",
	["%s: none of its buttons are there."] = "%s: Keine Schaltflächen vorhanden.",
	["There is no frame \"%s\". Frame names are case-sensitive."] = "Rahmen „%s“ fehlt. Groß-/Kleinschreibung beachten.",
	["Pick a frame. Left-click moves it. The mouse wheel picks the frame under it. Right-click or Escape stops."] = "Rahmen wählen: Linksklick verschiebt, Mausrad wählt darunter, Rechtsklick oder Escape beendet.",
	["This client cannot list its frames. Type /move FrameName instead."] = "Dieser Client kann Rahmen nicht auflisten. Nutze /move FrameName.",
	["Filter:"] = "Filter:",
	["Frame"] = "Rahmen",
	["Move"] = "Verschieben",
	["Puts an overlay on the frame. Drag the overlay to move the frame. Drag a gold handle to scale it. Hold Alt while you drag a handle to change the width or the height. Right-click when you are done. Shift-right-click hides the overlay so you can see the frame. The arrow keys move the frame while the cursor is on the overlay."] = "Overlay ziehen zum Verschieben, goldenen Griff zum Skalieren; Alt ändert die Maße. Rechtsklick beendet, Umschalt-Rechtsklick blendet die Farbe aus. Pfeiltasten verschieben unter dem Cursor.",
	["Keeps the frame hidden. The game cannot show it again."] = "Hält den Rahmen auch bei Anzeigeversuchen des Spiels verborgen.",
	["The game draws this part itself. You can hide it, but you cannot move it. This is the same setting as Options > Interface."] = "Das Spiel zeichnet diesen Bereich selbst: ausblendbar, nicht verschiebbar. Gleiche Einstellung wie Optionen > Oberfläche.",
	["This frame is not loaded now."] = "Dieser Rahmen ist derzeit nicht geladen.",
	["Layout for:"] = "Layout für:",
	["All heroes"] = "Alle Helden",
	["All heroes and classes use one layout."] = "Ein Layout für alle Helden und Klassen.",
	["This class"] = "Diese Klasse",
	["All the heroes of this class use one layout. It starts as a copy of the layout in use."] = "Gemeinsames Layout für diese Klasse. Beginnt als Kopie des aktiven Layouts.",
	["This hero"] = "Dieser Held",
	["Only this hero uses the layout. A hero is its name and its class, so the same name in another class has its own layout. It starts as a copy of the layout in use."] = "Nur für diesen Namen und diese Klasse. Gleicher Name mit anderer Klasse bleibt getrennt. Beginnt als Kopie des aktiven Layouts.",
	["Puts all the frames of this layout back where the game puts them. Push two times."] = "Setzt alle Rahmen dieses Layouts zurück. Zweimal klicken zum Bestätigen.",
	["Done Moving"] = "Verschieben beenden",
	["Removes the overlays from all the frames that you move."] = "Entfernt die Overlays aller verschobenen Rahmen.",
	["Pick Frame"] = "Rahmen auswählen",
	["Shows the frame under the cursor. Left-click to move it. The mouse wheel picks the frame under it. The frame then shows in the list under \"Your frames\". /move FrameName does the same with the name of a frame."] = "Rahmen unter dem Cursor anklicken, Mausrad wählt darunter. Er erscheint unter „Deine Rahmen“. Alternativ: /move FrameName.",
	["Your frames"] = "Deine Rahmen",
	["This class (%s)"] = "Diese Klasse (%s)",
	["Layout: %s"] = "Layout: %s",
	["Under the cursor: this window"] = "Unter dem Cursor: dieses Fenster",
	["Under the cursor: %s"] = "Unter dem Cursor: %s",
	["There is no named frame under the cursor."] = "Kein benannter Rahmen unter dem Cursor.",
	["Open or close MoveAnything!"] = "MoveAnything! öffnen oder schließen",
	["Move the frame under the cursor"] = "Rahmen unter dem Cursor verschieben",
	["Pick a frame to move"] = "Rahmen zum Verschieben auswählen",
	["Put the moved frames back in place"] = "Gewählte Positionen erneut anwenden",
	["Moves, scales and hides the parts of the interface."] = "Verschiebt, skaliert und verbirgt Oberflächenelemente.",
	["The key for MoveAnything! is %s."] = "Taste für MoveAnything!: %s.",
	["MoveAnything! has no key. Type /move key <key> to set one. Example: /move key F7."] = "Keine Taste gesetzt. Setzen mit /move key <key>, z. B. /move key F7.",
	["MoveAnything! has no key now."] = "Taste für MoveAnything! entfernt.",
	["The key %s opens MoveAnything! now. It no longer does %s."] = "%s öffnet jetzt MoveAnything! statt %s.",
	["The key %s opens MoveAnything! now."] = "%s öffnet jetzt MoveAnything!.",
	["Type /move to open or close the window. Type /move FrameName to move a frame by its name. Type /move pick to pick a frame on the screen. Type /move hide FrameName to hide or show a frame. Type /move done to stop moving all frames. Type /unmove FrameName to put a frame back where the game puts it. Type /move key <key> to set a key for the window. Type /movelist to see the saved layouts, /movecopy Name to copy one and /movedelete Name to delete one."] = "Befehle: /move (Fenster), /move FrameName (verschieben), /move pick (auswählen), /move hide FrameName (aus-/einblenden), /move done (beenden), /unmove FrameName (zurücksetzen), /move key <key> (Taste), /movelist (Liste), /movecopy Name (kopieren), /movedelete Name (löschen).",
	["Type /movecopy Name. /movelist shows the names."] = "Nutze /movecopy Name. Namen: /movelist.",
	["Type /movedelete Name. /movelist shows the names."] = "Nutze /movedelete Name. Namen: /movelist.",
	["Language: %s"] = "Sprache: %s",
	["Choose a language. Applies immediately. Automatic follows the game language."] = "Sprache wählen, gilt sofort. Automatisch folgt der Spielsprache.",
	["Language set to %s."] = "Sprache auf %s gesetzt.",
	["Unknown language. Use /move lang auto, en, pl, cs, de, pt, es, fr, ro, tr, ru, uk, zh, ja or ko."] = "Unbekannte Sprache. Auswahl: /move lang auto, en, pl, cs, de, pt, es, fr, ro, tr, ru, uk, zh, ja, ko.",
	["The frame \"%s\" is protected."] = "Der Rahmen „%s“ ist geschützt.",
};
