	["%s: none of its buttons are there."] = "%s: kullanılabilir düğme yok.",
	["There is no frame \"%s\". Frame names are case-sensitive."] = "\"%s\" çerçevesi yok. Büyük/küçük harfe dikkat et.",
	["Pick a frame. Left-click moves it. The mouse wheel picks the frame under it. Right-click or Escape stops."] = "Çerçeve seç. Sol tık taşır, tekerlek alttakini seçer, sağ tık veya Escape durdurur.",
	["This client cannot list its frames. Type /move FrameName instead."] = "Bu istemci çerçeveleri listeleyemiyor. /move FrameName kullan.",
	["Filter:"] = "Filtre:",
	["Frame"] = "Çerçeve",
	["Move"] = "Taşı",
