	["Keeps the frame hidden. The game cannot show it again."] = "Oyun göstermeye çalışsa bile çerçeveyi gizli tutar.",
	["The game draws this part itself. You can hide it, but you cannot move it. This is the same setting as Options > Interface."] = "Bu paneli oyun çizer: gizlenebilir ama taşınamaz. Seçenekler > Arayüz ile aynı ayardır.",
	["This frame is not loaded now."] = "Bu çerçeve şu anda yüklenmemiş.",
	["Layout for:"] = "Düzen kapsamı:",
	["All heroes"] = "Tüm kahramanlar",
	["All heroes and classes use one layout."] = "Tüm kahramanlar ve sınıflar tek düzen kullanır.",
	["This class"] = "Bu sınıf",
	["All the heroes of this class use one layout. It starts as a copy of the layout in use."] = "Bu sınıftaki tüm kahramanlar aynı düzeni kullanır. Başlangıçta etkin düzen kopyalanır.",
	["This hero"] = "Bu kahraman",
	["Only this hero uses the layout. A hero is its name and its class, so the same name in another class has its own layout. It starts as a copy of the layout in use."] = "Yalnızca bu ad ve sınıf için. Aynı adın başka sınıfı ayrı düzen kullanır. Başlangıçta etkin düzen kopyalanır.",
	["Puts all the frames of this layout back where the game puts them. Push two times."] = "Bu düzendeki tüm çerçeveleri sıfırlar. Onaylamak için iki kez tıkla.",
	["Done Moving"] = "Taşımayı bitir",
	["Removes the overlays from all the frames that you move."] = "Taşınan tüm çerçevelerin katmanlarını kaldırır.",
	["Pick Frame"] = "Çerçeve seç",
	["Shows the frame under the cursor. Left-click to move it. The mouse wheel picks the frame under it. The frame then shows in the list under \"Your frames\". /move FrameName does the same with the name of a frame."] = "İmlecin altındaki çerçeveye tıkla; tekerlek alttakini seçer. \"Çerçevelerin\" listesine eklenir. Alternatif: /move FrameName.",
	["Your frames"] = "Çerçevelerin",
	["This class (%s)"] = "Bu sınıf (%s)",
	["Layout: %s"] = "Düzen: %s",
	["Under the cursor: this window"] = "İmlecin altında: bu pencere",
	["Under the cursor: %s"] = "İmlecin altında: %s",
	["There is no named frame under the cursor."] = "İmlecin altında adlandırılmış çerçeve yok.",
	["Open or close MoveAnything!"] = "MoveAnything! aç veya kapat",
	["Move the frame under the cursor"] = "İmlecin altındaki çerçeveyi taşı",
	["Pick a frame to move"] = "Taşınacak çerçeveyi seç",
	["Put the moved frames back in place"] = "Seçilen konumları yeniden uygula",
	["Moves, scales and hides the parts of the interface."] = "Arayüz öğelerini taşır, ölçekler ve gizler.",
	["The key for MoveAnything! is %s."] = "MoveAnything! tuşu: %s.",
	["MoveAnything! has no key. Type /move key <key> to set one. Example: /move key F7."] = "Tuş atanmamış. /move key <key> ile ata; örnek: /move key F7.",
	["MoveAnything! has no key now."] = "MoveAnything! tuşu kaldırıldı.",
	["The key %s opens MoveAnything! now. It no longer does %s."] = "%s artık MoveAnything! açar; %s işlevini yapmaz.",
	["The key %s opens MoveAnything! now."] = "%s artık MoveAnything! açar.",
	["Type /move to open or close the window. Type /move FrameName to move a frame by its name. Type /move pick to pick a frame on the screen. Type /move hide FrameName to hide or show a frame. Type /move done to stop moving all frames. Type /unmove FrameName to put a frame back where the game puts it. Type /move key <key> to set a key for the window. Type /movelist to see the saved layouts, /movecopy Name to copy one and /movedelete Name to delete one."] = "Komutlar: /move (pencere), /move FrameName (taşı), /move pick (seç), /move hide FrameName (gizle/göster), /move done (bitir), /unmove FrameName (sıfırla), /move key <key> (tuş), /movelist (liste), /movecopy Name (kopyala), /movedelete Name (sil).",
	["Type /movecopy Name. /movelist shows the names."] = "/movecopy Name kullan. Adlar: /movelist.",
	["Type /movedelete Name. /movelist shows the names."] = "/movedelete Name kullan. Adlar: /movelist.",
	["Language: %s"] = "Dil: %s",
	["Choose a language. Applies immediately. Automatic follows the game language."] = "Dil seç; hemen uygulanır. Otomatik, oyun dilini izler.",
	["Language set to %s."] = "Dil ayarlandı: %s.",
	["Unknown language. Use /move lang auto, en, pl, cs, de, pt, es, fr, ro, tr, ru, uk, zh, ja or ko."] = "Bilinmeyen dil. Seçenekler: /move lang auto, en, pl, cs, de, pt, es, fr, ro, tr, ru, uk, zh, ja, ko.",
	["The frame \"%s\" is protected."] = "\"%s\" çerçevesi korumalıdır.",
};
