	["Your frames"] = "Твої рамки",
	["This class (%s)"] = "Цей клас (%s)",
	["Layout: %s"] = "Схема: %s",
	["Under the cursor: this window"] = "Під курсором: це вікно",
	["Under the cursor: %s"] = "Під курсором: %s",
	["There is no named frame under the cursor."] = "Під курсором немає іменованої рамки.",
	["Open or close MoveAnything!"] = "Відкрити або закрити MoveAnything!",
	["Move the frame under the cursor"] = "Перемістити рамку під курсором",
	["Pick a frame to move"] = "Вибрати рамку для переміщення",
	["Put the moved frames back in place"] = "Знову застосувати вибрані позиції",
	["Moves, scales and hides the parts of the interface."] = "Переміщує, масштабує та приховує елементи інтерфейсу.",
	["The key for MoveAnything! is %s."] = "Клавіша MoveAnything!: %s.",
	["MoveAnything! has no key. Type /move key <key> to set one. Example: /move key F7."] = "Клавішу не задано. Задай через /move key <key>, наприклад /move key F7.",
	["MoveAnything! has no key now."] = "Клавішу MoveAnything! видалено.",
	["The key %s opens MoveAnything! now. It no longer does %s."] = "%s тепер відкриває MoveAnything! замість дії %s.",
	["The key %s opens MoveAnything! now."] = "%s тепер відкриває MoveAnything!.",
	["Type /move to open or close the window. Type /move FrameName to move a frame by its name. Type /move pick to pick a frame on the screen. Type /move hide FrameName to hide or show a frame. Type /move done to stop moving all frames. Type /unmove FrameName to put a frame back where the game puts it. Type /move key <key> to set a key for the window. Type /movelist to see the saved layouts, /movecopy Name to copy one and /movedelete Name to delete one."] = "Команди: /move (вікно), /move FrameName (перемістити), /move pick (вибрати), /move hide FrameName (приховати/показати), /move done (готово), /unmove FrameName (скинути), /move key <key> (клавіша), /movelist (список), /movecopy Name (копіювати), /movedelete Name (видалити).",
	["Type /movecopy Name. /movelist shows the names."] = "Використовуй /movecopy Name. Назви: /movelist.",
	["Type /movedelete Name. /movelist shows the names."] = "Використовуй /movedelete Name. Назви: /movelist.",
	["Language: %s"] = "Мова: %s",
	["Choose a language. Applies immediately. Automatic follows the game language."] = "Вибери мову; застосовується одразу. Автоматичний режим стежить за мовою гри.",
	["Language set to %s."] = "Мову встановлено: %s.",
	["Unknown language. Use /move lang auto, en, pl, cs, de, pt, es, fr, ro, tr, ru, uk, zh, ja or ko."] = "Невідома мова. Варіанти: /move lang auto, en, pl, cs, de, pt, es, fr, ro, tr, ru, uk, zh, ja, ko.",
	["The frame \"%s\" is protected."] = "Рамка «%s» захищена.",
};
