	["The layout \"%s\" is copied into \"%s\"."] = "\"%s\" 배치를 \"%s\"에 복사했습니다.",
	["The layout \"%s\" is in use. Push Reset All to clear it."] = "\"%s\" 배치를 사용 중입니다. 모두 초기화로 비우세요.",
	["The layout \"%s\" is deleted."] = "\"%s\" 배치를 삭제했습니다.",
	["The saved layouts (in use: %s):"] = "저장된 배치 (사용 중: %s):",
	["%s: %d frames"] = "%s: 프레임 %d개",
	["Drag to move. Right-click when done."] = "드래그하여 이동하고 우클릭하여 완료하세요.",
	["Drag to scale"] = "드래그하여 배율 조절",
	["Hold Alt while you drag to change the width or the height."] = "Alt를 누른 채 드래그하여 너비나 높이를 바꾸세요.",
	["%s: none of its buttons are there."] = "%s: 사용 가능한 버튼이 없습니다.",
	["There is no frame \"%s\". Frame names are case-sensitive."] = "\"%s\" 프레임이 없습니다. 대소문자를 구분합니다.",
	["Pick a frame. Left-click moves it. The mouse wheel picks the frame under it. Right-click or Escape stops."] = "좌클릭으로 이동, 휠로 아래 프레임 선택, 우클릭 또는 Escape로 종료합니다.",
	["This client cannot list its frames. Type /move FrameName instead."] = "이 클라이언트는 프레임 목록을 지원하지 않습니다. /move FrameName을 사용하세요.",
	["Filter:"] = "필터:",
	["Frame"] = "프레임",
	["Move"] = "이동",
	["Puts an overlay on the frame. Drag the overlay to move the frame. Drag a gold handle to scale it. Hold Alt while you drag a handle to change the width or the height. Right-click when you are done. Shift-right-click hides the overlay so you can see the frame. The arrow keys move the frame while the cursor is on the overlay."] = "덮개를 드래그하여 이동하고 금색 손잡이로 배율을 조절합니다. Alt로 너비와 높이를 변경합니다. 우클릭으로 완료, Shift+우클릭으로 색상을 숨깁니다. 마우스를 올리고 방향키로 이동합니다.",
	["Keeps the frame hidden. The game cannot show it again."] = "게임이 다시 표시하려 해도 프레임을 숨긴 상태로 유지합니다.",
	["The game draws this part itself. You can hide it, but you cannot move it. This is the same setting as Options > Interface."] = "게임이 직접 그리는 패널로, 숨길 수 있지만 이동할 수 없습니다. 옵션의 인터페이스 설정과 같습니다.",
	["This frame is not loaded now."] = "이 프레임은 현재 불러오지 않았습니다.",
	["Layout for:"] = "배치 적용 대상:",
	["All heroes"] = "모든 영웅",
	["All heroes and classes use one layout."] = "모든 영웅과 직업이 하나의 배치를 사용합니다.",
	["This class"] = "현재 직업",
	["All the heroes of this class use one layout. It starts as a copy of the layout in use."] = "이 직업의 모든 영웅이 배치를 공유하며, 현재 배치를 복사하여 시작합니다.",
	["This hero"] = "현재 영웅",
	["Only this hero uses the layout. A hero is its name and its class, so the same name in another class has its own layout. It starts as a copy of the layout in use."] = "이 이름과 직업에만 적용합니다. 같은 이름이라도 직업이 다르면 별도 배치를 사용하며, 현재 배치를 복사하여 시작합니다.",
	["Puts all the frames of this layout back where the game puts them. Push two times."] = "이 배치의 모든 프레임을 복원합니다. 두 번 클릭하여 확인하세요.",
	["Done Moving"] = "이동 완료",
	["Removes the overlays from all the frames that you move."] = "이동 중인 모든 프레임의 덮개를 제거합니다.",
	["Pick Frame"] = "프레임 선택",
	["Shows the frame under the cursor. Left-click to move it. The mouse wheel picks the frame under it. The frame then shows in the list under \"Your frames\". /move FrameName does the same with the name of a frame."] = "마우스 아래 프레임을 클릭하여 이동하고 휠로 아래 프레임을 고릅니다. \"내 프레임\"에 추가됩니다. /move FrameName으로도 지정할 수 있습니다.",
	["Your frames"] = "내 프레임",
	["This class (%s)"] = "현재 직업 (%s)",
	["Layout: %s"] = "배치: %s",
	["Under the cursor: this window"] = "마우스 아래: 이 창",
	["Under the cursor: %s"] = "마우스 아래: %s",
	["There is no named frame under the cursor."] = "마우스 아래 이름이 있는 프레임이 없습니다.",
	["Open or close MoveAnything!"] = "MoveAnything! 열기 또는 닫기",
	["Move the frame under the cursor"] = "마우스 아래 프레임 이동",
	["Pick a frame to move"] = "이동할 프레임 선택",
	["Put the moved frames back in place"] = "설정한 위치 다시 적용",
	["Moves, scales and hides the parts of the interface."] = "인터페이스 요소를 이동하고 배율을 조절하거나 숨깁니다.",
	["The key for MoveAnything! is %s."] = "MoveAnything! 단축키: %s.",
	["MoveAnything! has no key. Type /move key <key> to set one. Example: /move key F7."] = "단축키가 없습니다. /move key <key>로 설정하세요. 예: /move key F7.",
	["MoveAnything! has no key now."] = "MoveAnything! 단축키를 해제했습니다.",
	["The key %s opens MoveAnything! now. It no longer does %s."] = "%s 키로 MoveAnything!을 열며 기존 %s 동작을 대체합니다.",
	["The key %s opens MoveAnything! now."] = "%s 키로 MoveAnything!을 엽니다.",
	["Type /move to open or close the window. Type /move FrameName to move a frame by its name. Type /move pick to pick a frame on the screen. Type /move hide FrameName to hide or show a frame. Type /move done to stop moving all frames. Type /unmove FrameName to put a frame back where the game puts it. Type /move key <key> to set a key for the window. Type /movelist to see the saved layouts, /movecopy Name to copy one and /movedelete Name to delete one."] = "명령어: /move (창), /move FrameName (이동), /move pick (선택), /move hide FrameName (표시 전환), /move done (완료), /unmove FrameName (초기화), /move key <key> (단축키), /movelist (목록), /movecopy Name (복사), /movedelete Name (삭제).",
	["Type /movecopy Name. /movelist shows the names."] = "/movecopy Name을 사용하세요. 이름 목록: /movelist.",
	["Type /movedelete Name. /movelist shows the names."] = "/movedelete Name을 사용하세요. 이름 목록: /movelist.",
	["Language: %s"] = "언어: %s",
	["Choose a language. Applies immediately. Automatic follows the game language."] = "언어를 선택하면 즉시 적용됩니다. 자동은 게임 언어를 따릅니다.",
	["Language set to %s."] = "언어를 %s(으)로 설정했습니다.",
	["Unknown language. Use /move lang auto, en, pl, cs, de, pt, es, fr, ro, tr, ru, uk, zh, ja or ko."] = "알 수 없는 언어입니다. 선택: /move lang auto, en, pl, cs, de, pt, es, fr, ro, tr, ru, uk, zh, ja, ko.",
	["The frame \"%s\" is protected."] = "\"%s\" 프레임은 보호되어 있습니다.",
};
